import { useTextArea } from '@dreadnought/react/logic';
export function Example() {
  const { textAreaProps, textAreaRef } = useTextArea({ rows: 3, autoSize: true });
  return <textarea {...textAreaProps} ref={textAreaRef} aria-label="Заметки" />;
}

import { TextAreaAdapter } from '@dreadnought/react/unstyled';
export function Example() {
  return <><label htmlFor="notes">Заметки</label><TextAreaAdapter id="notes" name="notes" rows={3} autoSize maxRows={8} /></>;
}
